package check

import (
	"context"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func fixtureModule(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	files := map[string]string{
		"go.mod": "module fixture\n\ngo 1.26\n",
		"main.go": `package fixture
type P struct { ok bool }
var global bool
func sideEffect() bool { return true }
func examine(a, b bool, p *P, values []bool) {
    if a || (a && b) {}
    for a && true {}
    if sideEffect() || true {}
    if p != nil && p.ok {}
    if values[0] || true {}
    if global || global {}
}
`,
		"generated.go": "// Code generated by fixture; DO NOT EDIT.\npackage fixture\nfunc generated(a bool) { if a || a {} }\n",
		"ignored.go":   "//go:build ignore\n\npackage fixture\nfunc ignored(a bool) { if a || a {} }\n",
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0600); err != nil {
			t.Fatal(err)
		}
	}
	return dir
}

func realEngine(t *testing.T) string {
	t.Helper()
	if path := os.Getenv("EGGLOG_BIN"); path != "" {
		return path
	}
	_, current, _, _ := runtime.Caller(0)
	path := filepath.Join(filepath.Dir(current), "..", "..", ".tools", "bin", "egglog.exe")
	if _, err := os.Stat(path); err != nil {
		t.Skip("build egglog first or set EGGLOG_BIN")
	}
	return path
}

func TestRunReportsOnlySafeSuggestions(t *testing.T) {
	t.Chdir(fixtureModule(t))
	got, err := Run(context.Background(), []string{"./..."}, realEngine(t))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 {
		t.Fatalf("got %d diagnostics: %+v; want 2", len(got), got)
	}
	if got[0].Before != "a || (a && b)" || got[0].After != "a" || got[0].Line != 6 {
		t.Fatalf("first diagnostic = %+v", got[0])
	}
	if got[1].Before != "a && true" || got[1].After != "a" || got[1].Line != 7 {
		t.Fatalf("second diagnostic = %+v", got[1])
	}
	for _, d := range got {
		if !strings.HasSuffix(d.File, "main.go") || d.Column <= 0 {
			t.Fatalf("bad diagnostic location: %+v", d)
		}
	}
}

func TestRunReportsPackageErrors(t *testing.T) {
	dir := fixtureModule(t)
	if err := os.WriteFile(filepath.Join(dir, "broken.go"), []byte("package fixture\nfunc broken( {"), 0600); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)
	_, err := Run(context.Background(), []string{"./..."}, realEngine(t))
	if err == nil {
		t.Fatal("syntax error was ignored")
	}
}

func TestRunReportsMissingEngine(t *testing.T) {
	t.Chdir(fixtureModule(t))
	_, err := Run(context.Background(), []string{"./..."}, filepath.Join(t.TempDir(), "missing"))
	if err == nil || !strings.Contains(err.Error(), "egglog") {
		t.Fatalf("missing engine error = %v", err)
	}
}

func TestRunSortsLocationsNumerically(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module fixture\n\ngo 1.26\n"), 0600); err != nil {
		t.Fatal(err)
	}
	source := "package fixture\nfunc f(a bool) {\nif a || a {}\n" + strings.Repeat("\n", 10) + "if a && true {}\n}\n"
	if err := os.WriteFile(filepath.Join(dir, "sample.go"), []byte(source), 0600); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)
	got, err := Run(context.Background(), []string{"./..."}, realEngine(t))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 || got[0].Line >= got[1].Line {
		t.Fatalf("diagnostics out of order: %+v", got)
	}
}

func TestRunSkipsDotImportedGlobals(t *testing.T) {
	dir := t.TempDir()
	if err := os.Mkdir(filepath.Join(dir, "dependency"), 0700); err != nil {
		t.Fatal(err)
	}
	files := map[string]string{
		"go.mod":               "module fixture\n\ngo 1.26\n",
		"dependency/values.go": "package dependency\nvar Flag bool\nvar Pointer *int\n",
		"main.go": `package fixture
import . "fixture/dependency"
func f(local bool) {
    if Flag || Flag {}
    if Pointer == nil || Pointer == nil {}
    if local || local {}
}`,
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(dir, filepath.FromSlash(name)), []byte(content), 0600); err != nil {
			t.Fatal(err)
		}
	}
	t.Chdir(dir)
	got, err := Run(context.Background(), []string{"./..."}, realEngine(t))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Before != "local || local" {
		t.Fatalf("dot-imported global was analyzed: %+v", got)
	}
}

func TestRunMissingEngineFailsOnCleanPackage(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module fixture\n\ngo 1.26\n"), 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "main.go"), []byte("package fixture\nfunc f(a bool) bool { return a }\n"), 0600); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)
	_, err := Run(context.Background(), []string{"./..."}, filepath.Join(t.TempDir(), "missing"))
	if err == nil || !strings.Contains(err.Error(), "egglog") {
		t.Fatalf("missing engine error = %v", err)
	}
}
